async function runExtract(inputPath, outputDir) {
  const markdown = fs.readFileSync(inputPath, "utf8");
  const parsed = parseArchive(markdown);
  const reconciled = reconcileTransactions(parsed);
  const items = applyExceptionReasons(reconciled.items, parsed.policyExceptions);
  const exceptions = buildExceptions(items);
