function buildExceptions(items) {
  return items.filter((row) => row.exception_reason);
}

function applyExceptionReasons(items, policyExceptions) {
  const policyByTxn = new Map();
  for (const p of policyExceptions || []) {
    if (!p || !p.transaction_id) continue;
    policyByTxn.set(p.transaction_id, p);
  }

  for (const row of items) {
    const reasons = [];

    const amt = Number(row.amount_usd);
    if (amt > 10000) reasons.push("over_limit");

    // compliance_hold (Brief 07 + Brief 09)
    if (row.status === "rejected") {
      const meta = row.__meta || {};
      const preDate = meta.pre_correction_date;
      const qualifying = (meta.qualifying_emails || []).filter((e) => e && e.sent);
      const hasHoldEmail = qualifying.some((e) => String(e.sent) >= String(preDate));
      if (hasHoldEmail) reasons.push("compliance_hold");
    }

    // policy_waiver (Brief 08)
    if (row.status === "approved" && amt > 10000) {
      const pol = policyByTxn.get(row.transaction_id);
      if (pol && String(pol.approved_by).toLowerCase() === "compliance") {
        reasons.push("policy_waiver");
      }
    }

    // retroactive_review (Brief 08)
    if (row.status === "reversed" && amt > 5000) {
      const meta = row.__meta || {};
      if (meta.status_changed_by_correction) reasons.push("retroactive_review");
    }

    reasons.sort();
    row.exception_reason = reasons.length ? reasons.join(";") : null;

    // Remove internal metadata from output rows
    delete row.__meta;
  }

  return items;
}

module.exports = { buildExceptions, applyExceptionReasons };
